UPDATE companies SET description='Michaelson Foreign & Domestic Car Parts has operated from South River, New Jersey, since 1926.

The company functions as an auto recycler, dismantling late‑model foreign and domestic vehicles to harvest reusable parts, glass, and accessories. Its South River facility is described as highly organized and meticulously clean, housing a massive inventory that is searchable online. In addition to walk‑in sales, Michaelson ships nationwide through its own e‑commerce site and an eBay store, offering tested components with fast delivery.

The firm’s network of nationwide parts resources supplements its own stock, ensuring buyers can locate hard‑to‑find items.

Michaelson emphasizes its long‑standing reputation as New Jersey’s top auto recycler, attributing its longevity to unmatched customer service, a clean and well‑organized yard, and a commitment to keeping the family tradition alive. The company says it evolved from a local operation to a coast‑to‑coast supplier while maintaining the personal touch of a family business.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Auto recycling", "Salvage yard operations", "Used auto parts sales", "Nationwide shipping", "E-commerce sales", "Parts testing"], "industries": ["Automotive", "Auto recycling", "Aftermarket auto parts"], "materials": ["Automotive vehicles (salvage)", "Used auto parts", "Automotive glass", "Automotive accessories"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded 1926 -> db", "Headquarters South River, NJ -> db", "Family-owned (Michaelson family) -> /about-us", "Auto recycler / salvage yard -> /", "Nationwide shipping via website and eBay -> /about-us", "Facility described as highly organized, meticulously clean -> /about-us", "Massive inventory of foreign and domestic used auto parts -> /about-us", "Fast delivery mentioned -> /", "Parts tested -> /", "Serving automotive community -> /about-us"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Since 1926, Michaelson has been working hard to earn its reputation as New Jersey''s top auto recycler.", "founded_year": "1926", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='michaelson-foreign-domestic-car-parts' AND approved AND profile IS NULL;
UPDATE companies SET description='Michigan Milk Producers Association (MMPA) is a dairy cooperative founded in 1916 and headquartered in Novi, Michigan.

The cooperative runs five dairy processing plants. Its largest facility in Ovid, Michigan, handles more than 5 million pounds of milk per day, producing butter, milk powder, condensed milk, cream, and ultrafiltered milk. A plant in Constantine, Michigan, processes nearly 3 million pounds daily into ultrafiltered milk, cream, and condensed skim milk, with an adjacent ethanol plant that converts dairy byproducts. In Remus, Michigan, a cottage cheese plant processes over 500,000 pounds daily. The Middlebury, Indiana plant, operated through the Middlebury Cheese Company subsidiary, focuses on barrel and delihorn cheeses sold wholesale and under the Heritage Ridge Creamery brand. The Canton, Ohio facility, home to the Superior Dairy and Creative Edge subsidiaries, produces fluid milk and ice cream for national distribution. A farm supply store in Mt. Pleasant serves members and the public.

MMPA sells dairy ingredients to food manufacturers that make salad dressing, infant formula, candy, ice cream, pudding, baked goods, cheese, and yogurt. Its retail brands supply ice cream and fluid milk directly to consumers. The cooperative also provides milk testing and farm supply services to its member farms across Michigan, Indiana, Ohio, and Wisconsin.

The association emphasizes quality and sustainability, noting its Safe Quality Foods certification, Green Agri‑Business designations for the Ovid and Constantine plants, and numerous World Dairy Expo championship awards. Members participate in the National Dairy F.A.R.M. program for animal care, and the cooperative maintains an FDA‑certified central laboratory for milk quality assurance.', certifications=ARRAY['Safe Quality Foods Certified','Green Agri‑Business Designation (Michigan Agribusiness Association)','FDA‑certified laboratory','European Union compliant']::text[], profile='{"capabilities": ["Dairy ingredient processing", "Butter production", "Milk powder production", "Condensed milk production", "Cream processing", "Ultrafiltered milk production", "Cheese manufacturing (barrel, delihorn, cottage cheese)", "Fluid milk processing", "Ice cream production", "Milk quality assurance testing", "Farm supply retail", "Ethanol production from dairy byproducts"], "industries": ["Dairy farming", "Food manufacturing", "Retail food and beverage", "Animal care (F.A.R.M. program)"], "materials": ["Raw milk", "Cream", "Skim milk", "Butter", "Cheese cultures", "Nonfat dry milk", "Condensed skim milk"], "equipment": [], "volume": "Ovid plant: over 5 million lbs milk/day; Constantine plant: nearly 3 million lbs milk/day; Remus plant: over 500,000 lbs milk/day", "lead_time": "", "tolerances": "", "built_on": ["Safe Quality Foods Certified", "Green Agri\u2011Business Designation (Ovid and Constantine plants)", "Multiple World Dairy Expo Championship Product Contest awards", "European Union compliant for export", "FDA\u2011certified central milk testing laboratory"], "facts_used": ["Founded in 1916 -> db", "Headquarters in Novi, Michigan -> /", "Member\u2011owned cooperative -> /", "Five processing plants in Michigan, Indiana, Ohio -> /", "Ovid plant processes over 5 million lbs milk daily -> /", "Constantine plant processes nearly 3 million lbs milk daily with adjacent ethanol facility -> /", "Remus plant produces cottage cheese at over 500,000 lbs milk daily -> /", "Middlebury plant produces barrel and delihorn cheeses -> /", "Canton plant produces fluid milk and ice cream -> /", "Farm supply store in Mt. Pleasant -> /", "Safe Quality Foods Certified -> /", "Green Agri\u2011Business Designation for Ovid and Constantine -> /", "World Dairy Expo Championship awards -> /", "European Union compliant -> /", "FDA\u2011certified central laboratory -> /", "Sells dairy ingredients to food manufacturers (salad dressing, infant formula, candy, etc.) -> /", "Retail ice cream and fluid milk -> /", "Members participate in National Dairy F.A.R.M. program -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "MMPA\u2019s largest plant is in Ovid and processes over 5 million pounds of milk daily into a range of core dairy ingredients including butter, milk powder, condensed milk and cream.", "founded_year": "1916", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["European Union compliant"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='michigan-milk-producers-association' AND approved AND profile IS NULL;
UPDATE companies SET description='The company was founded in 1965 by George Rogers as the Miniature Insulated Wire Company and incorporated under its current name in 1966. Now under third-generation family ownership, the business has grown from a small shop into a multi-generational manufacturer serving aerospace, medical, and industrial markets worldwide.

Micro-Tek specializes in custom drawing, flattening, stranding, insulating, cutting, and stripping of fine wire and cable down to .0009 inch (AWG #50). Its capabilities include PTFE fluoropolymer extrusion for coax cores, tubing, and cables; etching for bondability on PTFE, FEP, PFA, and ETFE; wire winding; and contract manufacturing. All processes—wire drawing, stranding, insulating, and tubing—are performed under one roof, supporting custom and short runs as well as high-volume production.

The company serves aerospace customers with micro-coaxial cable, shielded twisted pair cable, and high-performance coaxial core for avionics, satellite systems, and communication equipment. In the medical sector, it supplies PTFE coaxial core, flat wire, fluoropolymer tubing, and etched liners for surgical devices, diagnostic imaging, braiding, coiling, and sensors. Industrial clients use its custom wire and cable for automation systems and high-temperature manufacturing processes requiring chemical resistance and durability.

Micro-Tek emphasizes precision, holding tolerances as fine as ±0.0002 inch, and flexibility, offering small runs, large orders, and just-in-time or contract manufacturing. The company cites its decades of experience, ISO 9001:2015 certification, and long-term customer relationships as key differentiators.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["PTFE fluoropolymer extrusion", "Coax core manufacturing", "Tubing extrusion", "Cable manufacturing", "Fine wire drawing", "Braid wire manufacturing", "Wire flattening", "Wire stranding", "Wire insulating", "Wire cutting", "Wire stripping", "Etching for bondability (PTFE, FEP, PFA, ETFE)", "Wire winding services", "Contract manufacturing", "Toll manufacturing", "Custom stranding", "Micro-coaxial cable production", "Shielded twisted pair cable production", "Hook-up/lead wire production", "Sub-miniature hook-up wire production", "Flat wire manufacturing (ferrous and non-ferrous)", "FEP heat shrink tubing", "High-frequency data cable production", "PTFE capillary tubing production", "PTFE mono-filament production"], "industries": ["Aerospace", "Medical", "Industrial"], "materials": ["PTFE", "FEP", "PFA", "ETFE", "Stainless steel", "Silver-plated copper", "Bare copper", "Thermocouple alloys", "Ferrous alloys", "Nonferrous alloys"], "equipment": [], "volume": "Custom and short runs to high-volume production", "lead_time": "", "tolerances": "\u00b10.0002 in", "built_on": ["Tolerances as fine as \u00b10.0002 inch", "Handles small runs, large orders, and just-in-time or contract manufacturing", "Decades of experience in custom wire and cable manufacturing", "ISO 9001:2015 certified quality system", "All processes (drawing, stranding, insulating, tubing) under one roof"], "facts_used": ["Founded 1965 by George Rogers as Miniature Insulated Wire Company -> /about-us", "Incorporated 1966, now 3rd generation family-owned -> /about-us", "Headquarters in Cinnaminson, New Jersey -> db, /about-us", "30,000 