UPDATE companies SET description='Mid Michigan Wood Specialties was founded in 2006 in Lyons, Michigan. What began with three routers in a basement has grown into a manufacturing partner for cabinetmakers and builders across the United States.

The company specializes exclusively in cabinet components: cabinet doors, drawer fronts, dovetail drawer boxes, and face frames. Using precision woodworking and dovetail joinery, the shop produces parts built to customer specifications. Facility size, headcount, and annual volume are not disclosed.

Its customers include cabinetmakers, builders, and contractors throughout Michigan and the broader U.S. market. The firm serves residential and commercial construction projects that require ready-to-install door and drawer components.

Founded by former cabinetmakers, the business was built to solve the labor and scheduling pressures they knew firsthand. The team emphasizes on-time delivery of components that arrive ready to install, allowing builders to focus on assembly rather than part fabrication. By limiting its scope to doors and drawers, the company aims to reduce callbacks and keep projects on schedule.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Cabinet Doors", "Drawer Fronts", "Dovetail Drawer Boxes", "Face Frames"], "industries": ["Cabinetmaking", "Construction", "Millwork"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Built by tradespeople, for tradespeople", "Exclusive focus on cabinet components (doors, drawers, drawer boxes)", "Former cabinetmakers on staff who understand builder pressures", "Mission: deliver quality parts, on time, with zero stress", "Faster turnarounds on precision-built parts"], "facts_used": ["Founded 2006 -> db", "Headquarters Lyons, Michigan -> db", "Started with three routers in a basement -> /about", "Former cabinetmakers, built by tradespeople -> /about", "Makes cabinet doors, drawer fronts, dovetail drawer boxes, face frames -> / and /about", "Serves cabinetmakers, builders, contractors across Michigan and US -> /about", "Does not build cabinets, only components -> /about", "Mission: deliver quality parts, on time, with zero stress -> /about", "Built by tradespeople, for tradespeople -> /about", "Precision built parts -> /", "Faster turnarounds -> /", "For builders, by builders -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We don''t build cabinets - and we don''t try to. Instead, we put all our energy into the parts that builders trust us to get right: doors, drawers, and drawer boxes.", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}':