UPDATE companies SET description='Midwest Metal Fabrications has operated from Tallmadge, Ohio, for over 40 years. The company describes its origins as a hands-on partnership with customers, not merely a vendor relationship, a mindset that has driven steady growth.

The shop provides laser cutting up to 1-inch thick on a 5-by-10-foot table, press braking with 243 tons across a 14-foot opening, AWS-certified welding of stainless, aluminum, and carbon steel, CNC shearing on a 10-foot-wide shear, and CNC milling and turning from prototype through production. Metal finishing — powder coating, zinc plating, and galvanizing — is outsourced to qualified partners. Custom products include NEMA enclosures, weldments, steel bollards, and rack systems.

Customers span aerospace, automation, data centers, electrical contractors, food and beverage, housing, integrators, last-mile trucking, machine builders, manufacturing, nuclear, power, and transportation. Wind-energy components are also noted. The firm primarily serves Northeast Ohio — Akron, Cleveland, Canton, Columbus, Cincinnati, Toledo — but ships nationwide. Testimonials cite an Akron electrical contractor and Bevcorp in Eastlake as repeat clients.

The company emphasizes its collaborative approach and long-tenured team as differentiators. It holds ISO 9001:2015 and AS9100 certifications, and promotes competitive pricing, reliable turnaround, and a partner-oriented attitude — treating customers as partners rather than purchase orders. All work is performed in the USA.', certifications=ARRAY['ISO 9001:2015','AS9100']::text[], profile='{"capabilities": ["Laser cutting (up to 1\" thick, 5'' x 10'' table)", "Press braking (243 tons, 14'' wide)", "Welding (AWS-certified, stainless, aluminum, carbon steel)", "CNC shearing (10'' wide shear)", "Metal finishing (powder coating, zinc plating, galvanizing via partners)", "CNC milling and turning (prototype to production)", "Custom metal fabrication (NEMA enclosures, weldments, steel bollards, enclosures and rack systems)"], "industries": ["Aerospace", "Automation", "Data Centers", "Electrical Contractors and Distributors", "Food and Beverage", "Housing", "Integrators and Automators", "Last Mile Trucking", "Machine Builders", "Manufacturing", "Nuclear", "Power", "Transportation", "Wind Energy"], "materials": ["Stainless steel", "Aluminum", "Carbon steel"], "equipment": ["5'' x 10'' laser cutting table", "243-ton press brake with 14'' opening", "10'' wide CNC shear", "Multiple CNC machining centers"], "volume": "Prototype to production", "lead_time": "", "tolerances": "", "built_on": ["Average employee tenure of 16 years", "ISO 9001:2015 and AS9100 certified", "AWS-certified welders", "Laser cutting capacity up to 1\" thick on 5'' x 10'' table", "Press brake capacity 243 tons with 14'' wide opening"], "facts_used": ["Location: Tallmadge, Ohio -> db", "Over 40 years of experience -> /about-us", "Average employee tenure 16 years -> /about-us", "Full-service metal fabrication shop -> /about-us", "Laser cutting up to 1\" thick on 5'' x 10'' table -> /services", "Press brake 243 tons, 14'' wide -> /services", "AWS-certified welders -> /services", "CNC shearing 10'' wide shear -> /services", "Metal finishing via partners (powder coating, zinc plating, galvanizing) -> /services", "CNC machining prototype to production -> /services", "Custom metal products: NEMA enclosures, weldments, steel bollards, enclosures and rack systems -> /", "Industries served list -> /about-us", "ISO 9001:2015 and AS9100 certified -> / and db", "Serves Northeast Ohio and nationwide -> /about-us", "Testimonials from Alfred Abraham and Drazen Ramljak -> /", "Materials: stainless, aluminum, carbon steel -> /services", "Collaborative, partner-focused approach -> /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "From concept to completion, we help OEMs, engineers, and manufacturers streamline production with expert CNC machining, laser cutting, metal finishing, press breaking, and more.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='midwest-metal-fabrications' AND approved AND profile IS NULL;
UPDATE companies SET description='Midwest Molding operates from Plain City, Ohio, as a 100% employee-owned plastic injection molding company. The firm is ISO 9001 certified and emphasizes state-of-the-art manufacturing technologies to produce custom, high-quality, cost-competitive plastic parts and assemblies. No founding year or founders are disclosed in the available information.

The company provides custom injection molding for complex parts, including insert molding, multi-shot options, and gate cutting. Its capabilities span from early prototyping and mold design through full-scale mass production. Automation features include 6-axis robotic part removal, downstream automation, ultrasonic welding, and sub-assembly. The facility runs climate-controlled 24/7 with multiple all-electric injection molding machines, high-precision 5- and 6-axis servo robots, vision inspection systems, and cloud-based production monitoring. Tooling capacity reaches 40,000 lb, supporting hot runners, core pulls, and valve gates. Materials processed cover a wide variety of resins, including engineering-grade and high-temperature formulations.

Midwest Molding serves the automotive, medical, consumer products, and industrial sectors. The company positions itself as a partner from concept to full production, offering fast turnaround and flexible services backed by ISO-certified quality systems and skilled engineering and production teams.', certifications=ARRAY['ISO 9001']::text[], profile='{"capabilities": ["Custom injection molding", "Insert molding", "Multi-shot molding", "Gate cutting", "Prototype to production", "Mold design", "Robotic part removal", "Downstream automation", "Ultrasonic welding", "Sub-assembly", "Advanced material handling (engineering-grade and high-temperature resins)", "Quality inspection", "Vision system inspection", "Cloud-based production monitoring", "Tooling support (hot runners, core pulls, valve gates)", "All-electric injection molding"], "industries": ["Automotive", "Medical", "Consumer Products", "Industrial"], "materials": ["Engineering-grade resins", "High-temperature resins"], "equipment": ["All-electric injection molding machines", "5-axis servo robots", "6-axis servo robots", "Vision inspection systems", "Cloud-based production monitoring system"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% employee-owned", "ISO 9001 certified", "40,000 lb tool/die capacity", "Multiple all-electric injection molding machines with 5- and 6-axis servo robots", "Climate-controlled 24/7 operation with cloud-based production monitoring"], "facts_used": ["Location: Plain City, Ohio -> /", "Ownership: 100% employee-owned -> /", "Certification: ISO 9001 -> /", "Tool/die capacity: 40,000 lb -> /", "Automation: 6-axis robot automation -> /", "Operation: Climate controlled 24/7 -> /", "Machines: Multiple all-electric injection molding machines -> /", "Robots: High precision servo robots (5 & 6 axis) -> /", "Tooling support: hot runners, core pulls, valve gates -> /", "Inspection: Vision systems -> /", "Monitoring: Cloud-based production monitoring -> /", "Processes: Custo