UPDATE companies SET description='Founded in 1978, Mineral Fabrication & Machine Company Inc. has delivered construction and fabrication services from its base in Keyser, West Virginia, covering projects throughout the South, Midwest, and Northeast. The company’s core work includes building machine parts and complete machines, as well as designing and fabricating custom production machinery for other manufacturers to run high-volume lines. Its client list features the West Virginia Department of Transportation for public infrastructure work and industrial companies like Greer Industries, Inc., indicating a footprint in both government and heavy-industrial sectors. Management points to a reputation built on workmanship and a business style that has generated sustained word-of-mouth referrals as the driver of its long-term growth.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Construction fabrication", "Machine parts production", "Complete machine assembly", "Custom production machinery design and fabrication"], "industries": [], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Quality construction and fabrication since 1978", "Reputation built on workmanship excellence", "Business driven by client word-of-mouth referrals", "Serves South, Midwest, and Northeast regions"], "facts_used": ["Founded 1978 -> db", "Headquarters Keyser, West Virginia -> db", "Provides construction and fabrication -> db", "Serves South, Midwest, Northeast -> db", "Produces machine parts and machines -> db", "Designs custom production machinery for other manufacturers -> db", "Customer: West Virginia Department of Transportation -> db", "Customer: Greer Industries, Inc. -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We have also designed and fabricated machines for other companies so that they can mass-produce their products.", "founded_year": "1978", "employee_count": "", "