UPDATE companies SET description='Montana Food Equipment is a family-owned business based in Helena, Montana, founded in 1923 as Hobart Sales and Service. The company was purchased by the Caissey family in 1991, and Levi Caissey assumed ownership in 2010, running it with his wife Kristin. It operates from a 10,000-square-foot warehouse and a 6,000-square-foot showroom on Airport Road.

The company sells and services residential and commercial kitchen equipment, offering installation, maintenance, repair, and warranty work. Its 17-person staff includes technicians certified by the Commercial Food Equipment Service Association (CFESA) and trained by the EPA under Section 608 for refrigerant handling.

Commercial customers include grocery stores, delis, bakeries, meat shops, restaurants, schools, hospitals, and convenience stores across Montana and northern Idaho. Residential clients are home chefs seeking professional-grade appliances.

Montana Food Equipment emphasizes durable equipment and responsive service, citing a 24- to 48-hour standard response window and 12- to 24-hour emergency response. The company highlights its century-long local presence and factory-trained technicians as key differentiators.', certifications=ARRAY['CFESA Certified','EPA Section 608','Montana State Weights and Measures License']::text[], profile='{"capabilities": ["Kitchen equipment sales", "Equipment installation", "Preventive maintenance", "Repair and warranty service", "Parts sales", "CFESA-certified maintenance and repair", "EPA Section 608 refrigerant handling", "Montana State Weights and Measures compliance"], "industries": ["Grocery stores", "Delis", "Bakeries", "Meat shops", "Restaurants", "Schools", "Hospitals", "Convenience stores", "Residential"], "materials": [], "equipment": ["Hobart", "BlueStar", "True Residential", "Best", "Wolf", "Sub-Zero", "Cove", "Polito Ovens", "Forno Bravo"], "volume": "", "lead_time": "24-48 hours for standard service calls; 12-24 hours for emergency service calls", "tolerances": "", "built_on": ["CFESA-certified service technicians", "24-48 hour standard service response, 12-24 hour emergency response", "Factory-trained on all brands sold", "10,000 sq ft warehouse and 6,000 sq ft showroom", "Family-owned and operated since 1923"], "facts_used": ["Founded 1923 as Hobart Sales and Service -> /about", "Family-owned, Levi Caissey owner since 2010 -> /about", "10,000 sq ft warehouse, 6,000 sq ft showroom -> /about", "17-person staff -> /about", "CFESA certified technicians -> /about", "EPA Section 608 certified -> /about", "Montana State Weights and Measures licensed -> /about", "Service response times 24-48 hrs standard, 12-24 hrs emergency -> /", "Brands: Hobart, BlueStar, True, Wolf, Sub-Zero, Cove, Forno Bravo -> /", "Industries served: grocery, deli, bakery, meat shop, restaurant, school, hospital, convenience store -> /"], "company_type": "Distributor / reseller", "makes_produc